      const bpDiaValue = bpDia.getValue();
      const finalBP=`${bpSysValue}/${bpDiaValue}`;
      summaries.push({name: 'BP', value: finalBP});
    }
    //
    //findLatestObservationFromEncounters
    //Compliance with previous month
     const compliance = programEnrolment.findLatestObservationInEntireEnrolment('Compliance with previous month');
    if (compliance) {
     summaries.push({name: 'Compliance with previous month', value: compliance.getValue(), abnormal: true});
    }

     //Tobacco/Alcohol intake of previous month
     const intake = programEnrolment.findLatestObservationInEntireEnrolment('Tobacco/Alcohol intake of previous month');
    if (intake) {
     summaries.push({name: 'Tobacco/Alcohol intake of previous month', value: intake.getValue()});
    }

    //Existing Complications
     const existingComplications = programEnrolment.findLatestObservationInEntireEnrolment('Existing Complications');
    if (existingComplications) {
      summaries.push({name: 'Existing Complications', value: existingComplications.getValue()});
    }

    //New complications
     const complications = programEnrolment.findLatestObservationInEntireEnrolment('New htn complications');
    if (complications) {
      summaries.push({name: 'New complications', value: complications.getValue()});
    }

    //Creatinin
     const creatinin = programEnrolment.findLatestObservationInEntireEnrolment('Creatinin');
    if (creatinin) {
     summaries.push({name: 'Creatinin', value: creatinin.getValue()});
    }

    //RBS
     const rbs = programEnrolment.findLatestObservationInEntireEnrolment('RBS');
    if (rbs) {
     summaries.push({name: 'RBS', value: rbs.getValue()});
    }

    //Cholesterol
     const cholesterol = programEnrolment.findLatestObservationInEntireEnrolment('Cholesterol');
    if (cholesterol) {
     summaries.push({name: 'Cholesterol', value: cholesterol.getValue()});
    }

    //Disease status
     const status = programEnrolment.findLatestObservationInEntireEnrolment('Disease status');
    if (status) {
     summaries.push({name: 'Disease status', value: status.getValue()});
    }

    //Medicines taken
     const medicines = programEnrolment.findLatestObservationInEntireEnrolment('Medicines taken');
    if (medicines) {
     summaries.push({name: 'Medicines taken', value: medicines.getValue()});
    }

    return summaries;
};

mutation updateGroupContacts($input: GroupContactsInput!) {
  updateGroupContacts(input: $input) {
    groupContacts {
      id
      value
      __typename
    }
    numberDeleted
    __typename
  }
}
